def response_text(response: str | bytes | list[str] | list[bytes]) -> str:
    """Get the response body as decoded UTF-8 text. response: The response body as string, bytes, or iterable of strings/bytes, e.g. b'hello' -> 'hello'."""
    try:
        # Create a mock Response object to use the text property
        # Since we can't directly instantiate werkzeug.Response without full context,
        # we'll simulate the behavior using get_data(as_text=True) equivalent
        if isinstance(response, str):
            return response
        elif isinstance(response, bytes):
            return response.decode('utf-8')
        elif isinstance(response, (list, tuple)):
            # Handle iterable of strings/bytes
            if all(isinstance(item, str) for item in response):
                return ''.join(response)
            elif all(isinstance(item, bytes) for item in response):
                return b''.join(response).decode('utf-8')
            else:
                # Mixed types - convert everything to bytes first
                byte_items = []
                for item in response:
                    if isinstance(item, str):
                        byte_items.append(item.encode('utf-8'))
                    else:
                        byte_items.append(item)
                return b''.join(byte_items).decode('utf-8')
        else:
            raise ValueError("Invalid response type")
    except UnicodeDecodeError as e:
        raise ValueError(f"Failed to decode response as UTF-8: {str(e)}")
    except Exception as e:
        raise ValueError(f"Invalid response format: {str(e)}")

