def parse_accept_header(value: str | None) -> str:
    """Parse an Accept header and create an Accept object. value: The Accept header value to parse, e.g. 'text/html,application/json;q=0.9' -> 'text/html,application/json;q=0.9'"""
    try:
        accept_obj = Accept.from_header(value)
