def format_content_security_policy(policy: object) -> str:
    """Convert a ContentSecurityPolicy instance to a Content-Security-Policy header value.

    Args:
        policy: A ContentSecurityPolicy instance with policy directives

    Returns:
        A string representation of the policy suitable for HTTP headers

    Example:
        >>> from werkzeug.datastructures import ContentSecurityPolicy
        >>> policy = ContentSecurityPolicy({'default-src': "'self'", 'script-src': "'self' https://example.com"})
        >>> format_content_security_policy(policy)
        "default-src 'self'; script-src 'self' https://example.com"
