    Example:
        >>> format_http_date("2023-01-01")
        'Sun, 01 Jan 2023 00:00:00 GMT'
    """
    if timestamp is None:
        # Use current time
        timestamp = dt.datetime.now(dt.timezone.utc)
    elif isinstance(timestamp, str):
        # Try to parse the timestamp as a datetime string
        try:
            # Try common datetime formats
            for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d", "%Y-%m-%dT%H:%M:%S"):
                try:
                    parsed = dt.datetime.strptime(timestamp, fmt)
                    break
                except ValueError:
                    continue
            else:
                # If no format matches, treat as timestamp
                try:
                    parsed = dt.datetime.fromtimestamp(float(timestamp), tz=dt.timezone.utc)
                except ValueError:
                    raise ValueError(f"Invalid timestamp format: {timestamp!r}")
        except Exception as e:
            raise ValueError(f"Invalid timestamp: {timestamp!r}") from e
        timestamp = parsed
    elif isinstance(timestamp, (int, float)):
        # Treat as timestamp
        timestamp = dt.datetime.fromtimestamp(timestamp, tz=dt.timezone.utc)

    # Handle different types of timestamp inputs
    if isinstance(timestamp, dt.date):
        if not isinstance(timestamp, dt.datetime):
            # Assume plain date is midnight UTC
            timestamp = dt.datetime.combine(timestamp, dt.time(), tzinfo=dt.UTC)
        else:
            # Ensure datetime is timezone-aware
            timestamp = _dt_as_utc(timestamp)

        return email.utils.format_datetime(timestamp, usegmt=True)

    if hasattr(timestamp, 'tm_year'):
        # It's a struct_time
        timestamp = mktime(timestamp)

    return email.utils.formatdate(timestamp, usegmt=True)

from typing import Any


def match_url(path_info: str, method: str, map_adapter: Any) -> dict[str, str | list | dict]:
    """Match a URL path and method to a rule and return endpoint and values. path_info: the path to match, method: the HTTP method, map_adapter: a werkzeug MapAdapter instance. Returns a dict with 'endpoint' and 'values'. Example: match_url('/users/123', 'GET', adapter) -> {'endpoint': 'user_detail', 'values': {'id': '123'}}"""
    try:
        result = map_adapter.match(path_info=path_info, method=method)
        endpoint, values = result
        return {
            "endpoint": str(endpoint),
            "values": {str(k): str(v) for k, v in values.items()}
        }
    except Exception as e:
        raise ValueError(f"URL matching failed: {str(e)}")

from werkzeug.urls import iri_to_uri as _iri_to_uri


def iri_to_uri(iri: str) -> str:
    """Convert an IRI to a URI. All non-ASCII and unsafe characters are quoted. If the URL has a domain, it is encoded to Punycode. iri: The IRI to convert, e.g. 'http://☃.net/påth?q=èry%DF' -> 'http://xn--n3h.net/p%C3%A5th?q=%C3%A8ry%DF'."""
    try:
        return _iri_to_uri(iri)
    except Exception as e:
        raise ValueError(f"failed to convert IRI to URI: {str(e)}") from e

from werkzeug.utils import redirect
from werkzeug.wrappers import Response


def redirect_response(location: str, code: int = 303) -> dict[str, str | int]:
    """Create a response that redirects the client to the target location. location: The URL to redirect to. The client will interpret a relative URL (without the host) as relative to the host it's accessing. code: The redirect status code. This affects how the client issues the next request. Defaults to 303. Example: redirect_response('/success', 303) -> {'location': '/success', 'status_code': 303}"""
    if not isinstance(location, str):
        raise ValueError("Location must be a string")
    if not isinstance(code, int):
        raise ValueError("Code must be an integer")

    try:
        response = redirect(location, code)
        # Return the actual response object as a dictionary with its attributes
        return {
            "location": response.location,
            "status_code": response.status_code
        }
    except Exception as e:
        raise ValueError(f"Failed to create redirect response: {str(e)}")

from werkzeug.debug.repr import DebugReprGenerator


def generate_debug_representation(obj: object) -> str:
    """Create a debug representation of an object for better visualization in error messages. obj: any object to represent, e.g. {'a': 1} -> "<dict object at 0x...>"."""
    try:
        generator = DebugReprGenerator()
        return generator.repr(obj)
    except Exception as e:
        raise ValueError(f"failed to generate debug representation for object: {e}")

from urllib.parse import parse_qsl
from werkzeug.datastructures import ImmutableMultiDict


def parse_url_query_parameters(query_string: str) -> dict[str, list[str]]:
    """Parse the URL query parameters into an immutable multi-dict. query_string: The query string part of a URL, e.g. 'key=value&a=b' -> {'key': ['value'], 'a': ['b']}."""
    try:
        items = parse_qsl(
            query_string,
            keep_blank_values=True,
            errors="werkzeug.url_quote",
        )
        result = ImmutableMultiDict(items)
        # Convert to a JSON-friendly format
        output = {}
        for key in result.keys():
            output[key] = result.getlist(key)
        return output
    except Exception as e:
        raise ValueError(f"Failed to parse query string: {query_string!r}") from e

from werkzeug.sansio.http import parse_cookie


def parse_http_cookies(cookie: str | None = None) -> dict[str, str] | None:
    """Parse cookies from a Cookie header into a dictionary. cookie: The Cookie header string to parse, e.g. 'sessionid=abc123; csrftoken=xyz789' -> {'sessionid': 'abc123', 'csrftoken': 'xyz789'}."""
    try:
        result = parse_cookie(cookie)
        if result is None:
            return None
        # Convert ImmutableMultiDict to a dict[str, str] for JSON serialization
        # Each cookie key maps to a single value, so we take the first value
        return {key: value for key, value in result.items()}
    except Exception as e:
        raise ValueError(f"Failed to parse cookies: {str(e)}")

def check_if_response_is_json(mimetype: str) -> bool:
    """Check if the mimetype indicates JSON data, either 'application/json' or 'application/*+json'. mimetype: The MIME type of the response, e.g. 'application/json' -> true."""
    if mimetype is None:
        return False

    return mimetype == "application/json" or (
        mimetype.startswith("application/") 
        and mimetype.endswith("+json")
    )
